#include <iostream>
#include <vector>
using namespace std;

int main() {
  int N, M;
  cin >> N >> M;
  vector<int> a(M);
  for (auto& x : a) cin >> x;
  vector<int> re(N + 1);
  for (auto& x : a) re[x] = 1;
  vector<int> ans;
  for (int i = 1, j = 1; i <= N; i = ++j) {
    while (re[j]) j++;
    for (int k = j; k >= i; k--) ans.push_back(k);
  }
  for (int i = 0; i < N; i++) cout << ans[i] << " \n"[i + 1 == N];
}

#include<bits/stdc++.h>
using namespace std;
void dfs(int&u,vector<vector<int>>&x,vector<bool>&ok){
  ok[u]=true;
  for(auto v:x[u]){
    dfs(v,x,ok);
  }
  cout<<u+1<<" ";
}
int main(){
  int n,m;
  cin>>n>>m;
  vector<int>a(m);
  for(int i=0;i<m;i++)cin>>a[i];
  for(int i=0;i<m;i++)a[i]--;
  vector<vector<int>>x(n);
  for(auto i:a){
    x[i].push_back(i+1);
  }
  vector<bool>ok(n,false);
  for(int i=0;i<n;i++)if(!ok[i])dfs(i,x,ok);
}
